1	package nexusbench
2	
3	import (
4		"context"
5		"fmt"
6		"slices"
7		"strings"
8		"testing"
9	)
10	
11	// The preflights of the upstream operations (DEVDESK-534, NX-02b, step 1):
12	// OpCut (cut-upstream), OpRestore (restore-upstream) and OpReset (reset).
13	// Against the scripted kubectl of preflight_test.go, which records every
14	// "auth can-i" question in order; asked, inNamespace, seedQuestions and
15	// requireRepeatsTheQuestion come from preflight_seed_test.go.
16	//
17	// Choices of the tests, to settle with the code (they follow the plan):
18	//   - OpCut, OpRestore and OpReset are appended after OpSeed, in this order; no
19	//     earlier value moves.
20	//   - OpCut asks, in this order, all in the bench namespace: get deployments,
21	//     list pods, patch deployments --subresource=scale. It reads the upstream
22	//     Deployment, waits until no pod is left and scales it to zero: it needs no
23	//     port-forward, no Service and no claim.
24	//   - OpRestore asks exactly what OpSeed asks, in the same order (a port-forward,
25	//     EnsureUpstream and its claim reads, the scale). If one list changes, the
26	//     test that compares them says so.
27	//   - OpReset asks what OpRestore asks, then delete, create and patch on
28	//     persistentvolumeclaims (the apply --server-side of an absent claim needs
29	//     create). It asks no pods/exec: a reset never changes the admin password.
30	//   - None of the three reads the nodes: the REST calls and the images go through
31	//     the loopback, so PreflightResult.NodeIP is empty. readsNode is true for
32	//     OpUp, OpProvision and OpStatus only.
33	//   - All three refuse an absent namespace (NamespaceMissing) and a foreign one
34	//     (NamespaceForeign), like seed.
35	//   - A refused question ends the preflight there; nothing is ever written.
36	
37	// upstreamOpName names the three operations in sub-test titles and messages
38	// (testOpName of preflight_test.go does not know them).
39	var upstreamOpName = map[Op]string{OpCut: "cut", OpRestore: "restore", OpReset: "reset"}
40	
41	// upstreamOps are the three operations, in the order of the constants.
42	var upstreamOps = []Op{OpCut, OpRestore, OpReset}
43	
44	// claimWrites are the three questions only OpReset adds to those of OpRestore.
45	var claimWrites = []string{
46		"delete persistentvolumeclaims",
47		"create persistentvolumeclaims",
48		"patch persistentvolumeclaims",
49	}
50	
51	// cutQuestions are the questions of OpCut, in the order the tests expect.
52	var cutQuestions = []string{
53		"get deployments", "list pods", "patch deployments --subresource=scale",
54	}
55	
56	// questionsOf are the questions of an upstream operation, in order.
57	func questionsOf(op Op) []string {
58		switch op {
59		case OpCut:
60			return cutQuestions
61		case OpRestore:
62			return seedQuestions
63		case OpReset:
64			return slices.Concat(seedQuestions, claimWrites)
65		}
66		panic(fmt.Sprintf("no questions scripted for op %d", op))
67	}
68	
69	// denialOf turns "create pods --subresource=portforward" into the pair deny
70	// takes, ("create", "pods/portforward").
71	func denialOf(question string) (verb, resource string) {
72		fields := strings.Fields(question)
73		verb, resource = fields[0], fields[1]
74		if len(fields) > 2 {
75			resource += "/" + strings.TrimPrefix(fields[2], "--subresource=")
76		}
77		return verb, resource
78	}
79	
80	func TestRunPreflightUpstreamOpsAreAppended(t *testing.T) {
81		// The earlier values are pinned by TestRunPreflightOpSeedIsAppended; here the
82		// three new ones follow OpSeed, one after the other.
83		if OpCut != OpSeed+1 || OpRestore != OpCut+1 || OpReset != OpRestore+1 {
84			t.Errorf("OpSeed, OpCut, OpRestore, OpReset = %d, %d, %d, %d: want four consecutive values in this order",
85				OpSeed, OpCut, OpRestore, OpReset)
86		}
87		for name, v := range map[string]Op{"OpUp": OpUp, "OpProvision": OpProvision, "OpDown": OpDown, "OpStatus": OpStatus, "OpSeed": OpSeed} {
88			if want := map[string]Op{"OpUp": 0, "OpProvision": 1, "OpDown": 2, "OpStatus": 3, "OpSeed": 4}[name]; v != want {
89				t.Errorf("%s = %d, want %d: operations are appended, never renumbered", name, v, want)
90			}
91		}
92	}
93	
94	func TestRunPreflightUpstreamOpsAskTheirQuestionsInOrder(t *testing.T) {
95		for _, op := range upstreamOps {
96			t.Run(upstreamOpName[op], func(t *testing.T) {
97				p := Defaults()
98				f := newFakeKubectl(t, p).ours()
99				res, err := RunPreflight(context.Background(), f, p, op)
100				if err != nil {
101					t.Fatalf("RunPreflight: %v", err)
102				}
103				if got, want := asked(f), inNamespace(p, questionsOf(op)...); !slices.Equal(got, want) {
104					t.Errorf("questions =\n  %q\nwant\n  %q", got, want)
105				}
106				if want := (PreflightResult{NamespaceExists: true, NamespaceOurs: true}); res != want {
107					t.Errorf("result = %+v, want %+v", res, want)
108				}
109				requireReadOnly(t, f)
110			})
111		}
112	}
113	
114	func TestRunPreflightUpstreamOpsAskNothingOutsideTheNamespace(t *testing.T) {
115		// The three operations act on one namespace: no cluster-wide question and no
116		// -A (the NodePort scan is up's), and no pods/exec (no admin password change).
117		for _, op := range upstreamOps {
118			t.Run(upstreamOpName[op], func(t *testing.T) {
119				p := Defaults()
120				f := newFakeKubectl(t, p).ours()
121				if _, err := RunPreflight(context.Background(), f, p, op); err != nil {
122					t.Fatalf("RunPreflight: %v", err)
123				}
124				for _, q := range f.asked {
125					if q.allNamespaces || q.namespace != p.Namespace {
126						t.Errorf("question %q is not scoped to the namespace of the run", q)
127					}
128					if q.subresource == "exec" {
129						t.Errorf("question %q: an upstream operation never execs into a pod", q)
130					}
131				}
132				for _, line := range f.callLines() {
133					if strings.HasPrefix(line, "get services") {
134						t.Errorf("%s read the Services of the cluster (%q): the NodePort check is up's", upstreamOpName[op], line)
135					}
136				}
137			})
138		}
139	}
140	
141	func TestRunPreflightUpstreamOpsHonorTheNamespaceParameter(t *testing.T) {
142		for _, op := range upstreamOps {
143			t.Run(upstreamOpName[op], func(t *testing.T) {
144				p := Defaults()
145				p.Namespace = "nexus-bench-2"
146				p.UpstreamURL = upstreamFor(p.Namespace)
147				f := newFakeKubectl(t, p).ours()
148				if _, err := RunPreflight(context.Background(), f, p, op); err != nil {
149					t.Fatalf("RunPreflight: %v", err)
150				}
151				got := asked(f)
152				if len(got) != len(questionsOf(op)) {
153					t.Errorf("asked %d questions, want %d: %q", len(got), len(questionsOf(op)), got)
154				}
155				for _, q := range got {
156					if !strings.HasSuffix(q, " -n nexus-bench-2") {
157						t.Errorf("question %q is not scoped to the namespace of the run", q)
158					}
159				}
160				requireReadOnly(t, f)
161			})
162		}
163	}
164	
165	func TestRunPreflightUpstreamOpsStopAtTheFirstRefusedQuestion(t *testing.T) {
166		for _, op := range upstreamOps {
167			all := inNamespace(Defaults(), questionsOf(op)...)
168			for i, q := range questionsOf(op) {
169				verb, resource := denialOf(q)
170				t.Run(upstreamOpName[op]+"/"+verb+" "+resource, func(t *testing.T) {
171					p := Defaults()
172					f := newFakeKubectl(t, p).ours().deny(verb, resource)
173					_, err := RunPreflight(context.Background(), f, p, op)
174					be := requireDeployKind(t, err, Forbidden)
175					requireMentions(t, err, append([]string{verb}, strings.Split(resource, "/")...), nil)
176					requireRepeatsTheQuestion(t, be.Check, verb, resource)
177					if got, want := asked(f), all[:i+1]; !slices.Equal(got, want) {
178						t.Errorf("questions = %q, want them to stop at the refused one: %q", got, want)
179					}
180					requireReadOnly(t, f)
181				})
182			}
183		}
184	}
185	
186	func TestRunPreflightRestoreAsksWhatSeedAsks(t *testing.T) {
187		// restore needs exactly the rights of seed (the port-forward, EnsureUpstream
188		// with its claim reads, the scale), in the same order. The lists are compared
189		// so that a change on one side fails here, not in production.
190		if got, want := permissionsByOp[OpRestore], permissionsByOp[OpSeed]; len(got) == 0 || !slices.Equal(got, want) {
191			t.Errorf("permissionsByOp[OpRestore] =\n  %+v\nwant the list of OpSeed\n  %+v", got, want)
192		}
193		p := Defaults()
194		seed := newFakeKubectl(t, p).ours()
195		restore := newFakeKubectl(t, p).ours()
196		for op, f := range map[Op]*fakeKubectl{OpSeed: seed, OpRestore: restore} {
197			if _, err := RunPreflight(context.Background(), f, p, op); err != nil {
198				t.Fatalf("RunPreflight(%d): %v", op, err)
199			}
200		}
201		if !slices.Equal(asked(seed), asked(restore)) {
202			t.Errorf("restore asked\n  %q\nseed asked\n  %q", asked(restore), asked(seed))
203		}
204	}
205	
206	func TestRunPreflightResetAsksWhatRestoreAsksThenTheClaimWrites(t *testing.T) {
207		restore, reset := permissionsByOp[OpRestore], permissionsByOp[OpReset]
208		if len(restore) == 0 || len(reset) != len(restore)+len(claimWrites) || !slices.Equal(reset[:len(restore)], restore) {
209			t.Fatalf("permissionsByOp[OpReset] =\n  %+v\nwant the list of OpRestore, then %q", reset, claimWrites)
210		}
211		for i, q := range claimWrites {
212			verb, resource := denialOf(q)
213			want := permission{verb, resource, "", scopeNamespace}
214			if got := reset[len(restore)+i]; got != want {
215				t.Errorf("permissionsByOp[OpReset][%d] = %+v, want %+v", len(restore)+i, got, want)
216			}
217		}
218	}
