220	func TestRunPreflightOnlyResetAsksToWriteClaims(t *testing.T) {
221		for _, op := range []Op{OpCut, OpRestore} {
222			t.Run(upstreamOpName[op], func(t *testing.T) {
223				p := Defaults()
224				f := newFakeKubectl(t, p).ours()
225				if _, err := RunPreflight(context.Background(), f, p, op); err != nil {
226					t.Fatalf("RunPreflight: %v", err)
227				}
228				for _, q := range claimWrites {
229					if slices.Contains(asked(f), q+" -n "+p.Namespace) {
230						t.Errorf("%s asked %q: only reset recycles the claim", upstreamOpName[op], q)
231					}
232				}
233			})
234		}
235		// cut touches only the Deployment of the upstream: no claim, no tunnel, no Service.
236		p := Defaults()
237		f := newFakeKubectl(t, p).ours()
238		if _, err := RunPreflight(context.Background(), f, p, OpCut); err != nil {
239			t.Fatalf("RunPreflight(OpCut): %v", err)
240		}
241		for _, q := range asked(f) {
242			for _, banned := range []string{"persistentvolumeclaims", "portforward", "services", "namespaces", "secrets"} {
243				if strings.Contains(q, banned) {
244					t.Errorf("cut asked %q: it needs none of %s", q, banned)
245				}
246			}
247		}
248	}
