250	func TestRunPreflightUpstreamOpsDoNotReadTheNodes(t *testing.T) {
251		for _, op := range upstreamOps {
252			t.Run(upstreamOpName[op], func(t *testing.T) {
253				p := Defaults()
254				f := newFakeKubectl(t, p).ours()
255				res, err := RunPreflight(context.Background(), f, p, op)
256				if err != nil {
