271	func TestOpReadsNode(t *testing.T) {
272		// up, provision and status read the node address; down and the four
273		// operations that go through the loopback do not.
274		want := map[Op]bool{
275			OpUp: true, OpProvision: true, OpStatus: true,
276			OpDown: false, OpSeed: false, OpCut: false, OpRestore: false, OpReset: false,
277		}
278		for op, reads := range want {
279			if got := op.readsNode(); got != reads {
280				t.Errorf("Op(%d).readsNode() = %v, want %v", op, got, reads)
281			}
282		}
283		// And the preflight follows: status, up and provision still return the address.
284		for _, op := range []Op{OpUp, OpProvision, OpStatus} {
285			p := Defaults()
286			f := newFakeKubectl(t, p).ours()
